def unpack(text):
    d = {}
    for m in re.finditer(r'<<<FILE: (.+?)>>>\n(.*?)\n<<<END FILE: \1>>>', text, re.S):
        d[m.group(1)] = m.group(2)
    return d


def main(build):
    all_m = members()
    b1 = [f for f in B1 if f in all_m]
    b2 = [f for f in all_m if f not in b1]
    ok = True
    for tag, names in (("main_and_register", b1), ("compendia_papers_audits", b2)):
        text = pack(names)
        back = unpack(text)
        bad = [n for n in names
               if n not in back or back[n] != open(n, encoding="utf-8").read()]
        if bad:
            print(f"ROUND-TRIP FAIL {tag}: {bad[:5]}")
            ok = False
