        fn = f"The_Method_1_6_BUILD{build}_{tag}.md"
        open(fn, "w", encoding="utf-8").write(text)
        print(f"{fn}  members {len(names)}  bytes {len(text.encode('utf-8')):,}  round-trip OK")
    if not ok:
        sys.exit(1)


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "15")
