import re
L=open("The_Method_1_6___The_Register-2.md",encoding="utf-8").read().split("\n")
PY=re.compile(r'\b[A-Za-z_][A-Za-z0-9_]*\.py\b')
BN=re.compile(r'\bBuild \d+\b|\bBUILD-\d+\b')
OTHER=re.compile(r'retired at|recomputed at|at build time')
# entry number for each line
ent=None; entof={}
for i,l in enumerate(L,1):
    if l.startswith("### "):
        d=re.findall(r'\d+', l[4:]); ent=d[0] if d else ent
    entof[i]=ent
py_lines={}; bn_lines={}; oth_lines={}
for i,l in enumerate(L,1):
    if i<=73: continue
    if PY.search(l): py_lines[i]=PY.findall(l)
    if BN.search(l): bn_lines[i]=BN.findall(l)
    if OTHER.search(l) and not PY.search(l) and not BN.search(l): oth_lines[i]=OTHER.findall(l)
from collections import Counter
print("A. .py NAMES  — lines:",len(py_lines)," occurrences:",sum(len(v) for v in py_lines.values()))
print("   distinct scripts:",dict(Counter(x for v in py_lines.values() for x in v)))
print("B. BUILD NUMBERS — lines:",len(bn_lines),[ (i,entof[i],v) for i,v in bn_lines.items()])
print("C. OTHER PHRASE ONLY — lines:",len(oth_lines))
for i,v in oth_lines.items():
    print(f"   R{entof[i]} line {i} {v}: {L[i-1].strip()[:150]}")
EOF

